// Validation helper
window.isValidWord = function(inputWord, combo) {
    if (!inputWord || typeof inputWord !== 'string') return false;
    const cleanWord = inputWord.trim().toLowerCase();
    if (cleanWord.length < 2) return false;
    
    const cleanCombo = (combo || '').trim().toLowerCase();
    const normWord = window.normalizeWord(cleanWord);
    const normCombo = window.normalizeWord(cleanCombo);

    // 1. Must contain the letter combination (both raw and normalized)
    const containsCombo = cleanWord.includes(cleanCombo) || normWord.includes(normCombo) || cleanWord.includes(normCombo);
    if (!containsCombo) return false;

    // 2. Check in Dictionary (raw or normalized)
    if (window.WORD_DICTIONARY.has(cleanWord) || window.WORD_DICTIONARY.has(normWord)) {
        return true;
    }

    // 3. Fallback for valid words: if length >= 3 and has at least one vowel
    const vowels = /[aeiouəıöü]/i;
    if (cleanWord.length >= 3 && vowels.test(cleanWord)) {
        return true;
    }

    return false;
};
